mapper.insert:
INSERT IGNORE INTO ifj_etl_checkpoint ( task_id, checkpoint_key, source_fingerprint, watermark_type, watermark_value, tie_breaker_value, last_instance_id, version ) SELECT #{checkpoint.taskId}, #{checkpoint.checkpointKey}, #{checkpoint.sourceFingerprint}, #{checkpoint.watermarkType}, #{checkpoint.watermarkValue}, #{checkpoint.tieBreakerValue}, #{checkpoint.lastInstanceId}, 0 FROM ifj_instance instance_record WHERE instance_record.id = #{checkpoint.lastInstanceId}
AND instance_record.execution_fence = #{permit.fenceToken} AND EXISTS ( SELECT 1 FROM ifj_trigger_work_item work_item WHERE work_item.trigger_id = instance_record.trigger_id AND work_item.status = 'CLAIMED' AND work_item.claim_token = #{permit.claimToken} AND work_item.fence_token = #{permit.fenceToken} AND work_item.lease_deadline > CURRENT_TIMESTAMP(3) )
AND EXISTS ( SELECT 1 FROM ifj_trigger_work_item work_item WHERE work_item.trigger_id = instance_record.trigger_id AND work_item.status = 'SUSPENDED' AND work_item.fence_token = instance_record.execution_fence )

