UPDATE ifj_etl_checkpoint
SET watermark_value = #{checkpoint.watermarkValue},
    tie_breaker_value = #{checkpoint.tieBreakerValue},
    last_instance_id = #{checkpoint.lastInstanceId},
    version = version + 1,
    update_time = CURRENT_TIMESTAMP(3)
WHERE task_id = #{checkpoint.taskId}
  AND checkpoint_key = #{checkpoint.checkpointKey}
  AND source_fingerprint = #{checkpoint.sourceFingerprint}
  AND watermark_type = #{checkpoint.watermarkType}
  AND version = #{expectedVersion}

    
    
        AND EXISTS (
            SELECT 1 FROM ifj_instance instance_record
            JOIN ifj_trigger_work_item work_item
              ON work_item.trigger_id = instance_record.trigger_id
            WHERE instance_record.id = #{checkpoint.lastInstanceId}
              AND instance_record.execution_fence = #{permit.fenceToken}
              AND work_item.status = 'CLAIMED'
              AND work_item.claim_token = #{permit.claimToken}
              AND work_item.fence_token = #{permit.fenceToken}
              AND work_item.lease_deadline > CURRENT_TIMESTAMP(3)
        )
    
    
        AND EXISTS (
            SELECT 1 FROM ifj_instance instance_record
            JOIN ifj_trigger_work_item work_item
              ON work_item.trigger_id = instance_record.trigger_id
            WHERE instance_record.id = #{checkpoint.lastInstanceId}
              AND work_item.status = 'SUSPENDED'
