mapper.insert:
MERGE INTO ifj_etl_checkpoint target USING ( SELECT #{checkpoint.taskId} AS task_id, #{checkpoint.checkpointKey} AS checkpoint_key, #{checkpoint.sourceFingerprint} AS source_fingerprint, #{checkpoint.watermarkType} AS watermark_type, #{checkpoint.watermarkValue} AS watermark_value, #{checkpoint.tieBreakerValue} AS tie_breaker_value, #{checkpoint.lastInstanceId} AS last_instance_id FROM ifj_instance instance_record WHERE instance_record.id = #{checkpoint.lastInstanceId}
AND instance_record.execution_fence = #{permit.fenceToken} AND EXISTS ( SELECT 1 FROM ifj_trigger_work_item work_item WHERE work_item.trigger_id = instance_record.trigger_id AND work_item.status = 'CLAIMED' AND work_item.claim_token = #{permit.claimToken} AND work_item.fence_token = #{permit.fenceToken} AND work_item.lease_deadline > CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)) )
AND EXISTS ( SELECT 1 FROM ifj_trigger_work_item work_item WHERE work_item.trigger_id = instance_record.trigger_id AND work_item.status = 'SUSPENDED' AND work_item.fence_token = instance_record.execution_fence )
) source ON (target.task_id = source.task_id AND target.checkpoint_key = source.checkpoint_key) WHEN NOT MATCHED THEN INSERT ( task_id, checkpoint_key, source_fingerprint, watermark_type, watermark_value, tie_breaker_value, last_instance_id, version ) VALUES ( source.task_id, source.checkpoint_key, source.source_fingerprint, source.watermark_type, source.watermark_value, source.tie_breaker_value, source.last_instance_id, 0 )
